const ListRow5_data2: ListRow5Data[] = [
    { text: "It can only read.", text2: " It can show you a campaign that's wasting budget in seconds, but you still switch to the Ads dashboard to pause it yourself. Good for analysis, only half of an actual workflow." },
    { text: "Not in the browser.", text2: " It runs as a program on your computer, so it only works in AI tools you install: Claude Code, Cursor, Gemini, VS Code. The browser versions of Claude (claude.ai) and ChatGPT can't reach it." },
    { text: "The same question can return different numbers.", text2: " You ask in plain English, and the AI translates that into a precise report query on its own, a little differently each time. So a figure it gives you is a quick read, not a final number. Confirm anything you'll report on against the Ads dashboard first." },
    { text: "Google only.", text2: " No Meta, no LinkedIn. Every other platform is a separate setup." }
];
