const Tile3_data: Tile3Data[] = [
    { id: "reka-accordion-trigger-v-0-20-0", label: "Is the Google Ads MCP free?", arialabelledby: "reka-accordion-trigger-v-0-20-0", id2: "reka-collapsible-content-v-0-20-1", description: "Yes. Google's official server (github.com/googleads/google-ads-mcp) is open-source and free. You run it locally via pipx. There is no hosted version and no subscription. Your only cost is the time it takes to set up, which is real." },
    { id: "reka-accordion-trigger-v-0-20-2", label: "Can the Google Ads MCP create or pause campaigns?", arialabelledby: "reka-accordion-trigger-v-0-20-2", id2: "reka-collapsible-content-v-0-20-3", description: "No. The official server is strictly read-only. Google's docs say it 'cannot modify bids, pause campaigns, or create new assets.' It has three tools, all for reading data. If you need to make changes, you need a different tool with write access." },
    { id: "reka-accordion-trigger-v-0-20-4", label: "Does the Google Ads MCP work with claude.ai or ChatGPT on the web?", arialabelledby: "reka-accordion-trigger-v-0-20-4", id2: "reka-collapsible-content-v-0-20-5", description: "No. The official server runs locally on your machine, so it only works with clients that launch local processes: Claude Code (the CLI), Cursor, Gemini CLI, Gemini Code Assist, and VS Code. claude.ai web and ChatGPT web connect to hosted URLs only, and Google does not host this server." },
    { id: "reka-accordion-trigger-v-0-20-6", label: "Why do I get 'this app is being tested' when I authenticate?", arialabelledby: "reka-accordion-trigger-v-0-20-6", id2: "reka-collapsible-content-v-0-20-7", description: "Your OAuth consent screen is in Testing mode and the Google account you signed in with is not on the test users list. Add both your own email and your Google Ads login email as test users in the Google Cloud console, then try again." },
    { id: "reka-accordion-trigger-v-0-20-8", label: "My developer token only works on test accounts. How do I fix it?", arialabelledby: "reka-accordion-trigger-v-0-20-8", id2: "reka-collapsible-content-v-0-20-9", description: "Your token has Test Account access, which can't read real campaigns. Google's automatic review usually grants Explorer access (which reads real accounts) the moment you submit the API access form, so a Test result means that auto-review couldn't clear you. Apply for Basic access in the Google Ads API Center and wait; Google targets a couple of business days, but the queue can run longer." },
    { id: "reka-accordion-trigger-v-0-20-10", label: "Do I need a Google Ads manager (MCC) account?", arialabelledby: "reka-accordion-trigger-v-0-20-10", id2: "reka-collapsible-content-v-0-20-11", description: "Yes, to get a developer token. The API Center only appears on a manager account, and the token request form lives there. Creating a manager account is free. If you access your ad account through that manager, set GOOGLE_ADS_LOGIN_CUSTOMER_ID to the manager's ID, digits only." },
    { id: "reka-accordion-trigger-v-0-20-12", label: "Can I use a service account instead of OAuth?", arialabelledby: "reka-accordion-trigger-v-0-20-12", id2: "reka-collapsible-content-v-0-20-13", description: "Not for Google Ads. Service accounts can't be added as users in Google Ads, so they have zero access to your campaigns. Use user OAuth with your own client, which is what this guide walks through." },
    { id: "reka-accordion-trigger-v-0-20-14", label: "Will the official Google Ads MCP ever support writing or editing campaigns?", arialabelledby: "reka-accordion-trigger-v-0-20-14", id2: "reka-collapsible-content-v-0-20-15", description: "Google hasn't committed to it. There is clear demand for write access, but no date and no promise. If you need to make changes today, you need a hosted MCP that already has write access, such as AdKit." }
];
